args.query:
\d api.company
\d api.application
\d api.app_user
select * from api.app_user;
select grantee,table_name,privilege_type from information_schema.role_table_grants where table_schema='api' order by 2,1;
select schemaname,tablename,policyname,roles,cmd,qual,with_check from pg_policies;
select relname,relrowsecurity,relforcerowsecurity from pg_class where relnamespace='api'::regnamespace and relkind in ('r','v');
select id,name,inn,funding_limit from api.company;

select * from api.status order by 1;
select id,number,company_id,status_id,amount from api.application order by id;
select proname from pg_proc where pronamespace='priv'::regnamespace;
select pg_get_functiondef('priv.my_company'::regproc);
select tgname, tgrelid::regclass from pg_trigger where not tgisinternal;
\d api.company
select conname,pg_get_constraintdef(oid) from pg_constraint where connamespace='api'::regnamespace;

select proname, proacl from pg_proc where pronamespace='priv'::regnamespace;
select nspname, nspacl from pg_namespace where nspname in ('priv','api');
select pg_get_functiondef('priv.login'::regproc);

grant usage on schema api, priv to lawyer;
alter table api.company add column ref_key uuid unique;
update api.company set ref_key='58009517-9772-57c0-8c12-180dc192012c' where inn='7700001009';
update api.company set ref_key='0221ab04-86e6-5a00-8275-e75cc0af4ebe' where inn='7700002018';
update api.company set ref_key='b7da7363-223d-57d3-b23b-1e939f613502' where inn='7700003027';
create table api.contract(
 id integer generated always as identity primary key,
 number text not null unique,
 application_id integer not null references api.application(id),
 amount numeric not null check (amount>0),
 signed_on date,
 status text not null default 'Проект' check (status in ('Проект','Подписан')));
create function priv.check_contract() returns trigger language plpgsql security definer set search_path=api as $$
begin
 if not exists(select 1 from api.application where id=new.application_id and status_id=priv.status_id('Одобрена')) then
  raise exception 'Договор можно заключить только по одобренной заявке';
 end if;
 return new;
end$$;
create trigger contract_check before insert or update on api.contract for each row execute function priv.check_contract();
alter table api.contract enable row level security;
create policy admin_all on api.contract for all to fund_admin using(true) with check(true);
create policy lawyer_all on api.contract for all to lawyer using(true) with check(true);
create policy applicant_read on api.contract for select to applicant using (exists(select 1 from api.application a where a.id=application_id and a.company_id=priv.my_company()));
grant select,insert,update,delete on api.contract to fund_admin;
grant select,insert,update on api.contract to lawyer;
grant select on api.contract to applicant;
grant select on api.application, api.company, api.status to lawyer;
create policy lawyer_read on api.application for select to lawyer using(true);
update api.app_user set role='lawyer' where login='lawyer1';
create view api.limit_balance with (security_invoker=false) as
select c.name as company, c.funding_limit, ap.approved, coalesce(ct.contracted,0) as contracted,
 c.funding_limit - coalesce(ct.contracted,0) as remaining
from api.company c
join (select company_id, sum(amount) approved from api.application where status_id=priv.status_id('Одобрена') group by 1) ap on ap.company_id=c.id
left join (select a.company_id, sum(k.amount) contracted from api.contract k join api.application a on a.id=k.application_id group by 1) ct on ct.company_id=c.id;
grant select on api.limit_balance to fund_admin, lawyer, expert;
notify pgrst,'reload schema';
